SELECT "t5"."line_id", "t5"."item_on_hand", COALESCE("t7"."quantity_on_hand", 0) AS "variant_on_hand"
FROM (SELECT "t2"."line_id", "t2"."request_number", "t2"."item", "t2"."quantity", "t2"."unit_price", "t2"."line_value", "t2"."reason", "t2"."requested_resolution", "t2"."requested_variant", "t2"."customer", "t2"."order_number", "t2"."requested_date", "t2"."customer_id", "t2"."addr", "t2"."cdemo", "t2"."hdemo", "t2"."birth_year", "t2"."center", "t4"."as_of_date", "t4"."quantity_on_hand", COALESCE("t4"."quantity_on_hand", 0) AS "item_on_hand"
        FROM (SELECT "t1"."line_id", "t1"."request_number", "t1"."item", "t1"."quantity", "t1"."unit_price", "t1"."line_value", "t1"."reason", "t1"."requested_resolution", "t1"."requested_variant", "t1"."customer", "t1"."order_number", "t1"."requested_date", "customer"."customer_id", "customer"."addr", "customer"."cdemo", "customer"."hdemo", "customer"."birth_year", "customer"."center"
                FROM (SELECT "line_id", "request_number", "item", "quantity", "unit_price", "quantity" * "unit_price" AS "line_value", "reason", "requested_resolution", "requested_variant", "customer0" AS "customer", "order_number", "requested_date"
                        FROM (SELECT "return_request_line"."line_id", "return_request_line"."request_number", "return_request_line"."line_no", "return_request_line"."item", "return_request_line"."quantity", "return_request_line"."unit_price", "return_request_line"."reason", "return_request_line"."requested_resolution", "return_request_line"."requested_variant", "return_request_line"."state", "return_request_line"."way", "return_request_line"."customer", "return_request"."customer" AS "customer0", "return_request"."order_number", "return_request"."channel", "return_request"."requested_date", "return_request"."state" AS "state0"
                                FROM "return_request_line"
                                    INNER JOIN "return_request" ON "return_request_line"."request_number" = "return_request"."request_number") AS "t"
                        WHERE "t"."state" = 'received') AS "t1"
                    INNER JOIN "customer" ON "t1"."customer" = "customer"."sk") AS "t2"
            LEFT JOIN (SELECT "inventory"."as_of_date", "inventory"."item", "inventory"."warehouse", "inventory"."quantity_on_hand"
                FROM "inventory"
                    INNER JOIN (SELECT "item", "warehouse", MAX("as_of_date") AS "_ttrp_latest_n29"
                        FROM "inventory"
                        GROUP BY "item", "warehouse") AS "t3" ON "inventory"."item" = "t3"."item" AND "inventory"."warehouse" = "t3"."warehouse" AND "inventory"."as_of_date" = "t3"."_ttrp_latest_n29") AS "t4" ON "t2"."item" = "t4"."item" AND "t2"."center" = "t4"."warehouse") AS "t5"
    LEFT JOIN (SELECT "inventory1"."as_of_date", "inventory1"."item", "inventory1"."warehouse", "inventory1"."quantity_on_hand"
        FROM "inventory" AS "inventory1"
            INNER JOIN (SELECT "item", "warehouse", MAX("as_of_date") AS "_ttrp_latest_n29"
                FROM "inventory"
                GROUP BY "item", "warehouse") AS "t6" ON "inventory1"."item" = "t6"."item" AND "inventory1"."warehouse" = "t6"."warehouse" AND "inventory1"."as_of_date" = "t6"."_ttrp_latest_n29") AS "t7" ON "t5"."requested_variant" = "t7"."item" AND "t5"."center" = "t7"."warehouse"
